          "ifNot": ["placed_stone", "cairn5"],
          "actions": [
            { "action": "addcondition", "parameters": ["placed_stone"], "scope": "player" },
            { "action": "addcondition", "parameters": ["cairn5"], "scope": "world" },
            { "action": "setlocationdescription", "parameters": ["2", "The path zigzags up the cliff face, cut into the rock and worn into a groove by feet. Halfway up there is a flat ledge that looks out over the whole bay. A proper cairn stands here now, five stones high, and it can be seen from the beach. Nobody built it alone. The lighthouse is north; the beach is south."] },
            { "action": "describe", "parameters": ["You set the fifth stone and it's done, or as done as a cairn gets. Five people who never met stood here one after another and did the same small thing. You'd call it a monument if it weren't so modest."] }
