            { "action": "addcondition", "parameters": ["placed_stone"], "scope": "player" },
            { "action": "describe", "parameters": ["The cairn is as tall as the wind will allow. You set your stone at its foot among the others there, a small ring that grows a little with each person who comes. Nobody will know which one is yours. You will."] }
