        {
          "interactionId": "cliff-view",
          "triggers": ["*view*", "*bay*", "*look out*", "*ledge*"],
          "actions": [
            { "action": "describe", "parameters": ["From the ledge you can see the whole curve of the bay: the wreck on the sand, the marsh going silver in the last of the light, and the jetty poking out into water that gets darker the further out you look. Out past the jetty, very far away, something might be a boat waiting. Or it might be nothing."] }
          ]
